//! One JSON Schema per emitter, generated from the registry of the running binary.
//!
//! The schema is the ground truth of an emitter's audit format: every registered part, context
//! and vocabulary enum appears under `$defs`, with the doc comments as descriptions. It is
//! generated by a test in a crate that links every contributing crate, committed at
//! `audit-format/schema.json`, validated against by the tests, diffed across the merge base by
//! the format checker, and published to the documentation site.
//!
//! A crate cannot see another crate's registrations unless the linker keeps that crate's
//! objects, which it does only when something references them. So the schema is assembled in
//! two steps that need no linker cooperation: every crate that declares audit types commits a
//! **crate schema**, the definitions of its own types, written by its own unit tests
//! ([`crate_schema`]); and one test in a crate that sees every crate schema file merges them
//! per emitter into the committed schema ([`merge_crate_schemas`]).
//!
//! Two properties make the extra step worth it, and both are lost by generating the schema in
//! one place. A crate's schema is written by that crate's own test binary, where its
//! registrations are certainly linked, so a definition cannot go missing without a test
//! failing; and the file sits in the crate, so a pull request touching one crate shows that
//! crate's schema diff next to the change that caused it.
//!
//! Available under `test-utils`, so the tests of other emitting crates generate their crate
//! schema with this implementation. Debug builds only, like the registry it reads: see
//! [`Registration::require_registry`].

use std::collections::{BTreeMap, BTreeSet};

use schemars::{SchemaGenerator, generate::SchemaSettings};
use serde_json::{Map, Value, json};

use super::part::{Kind, Registration};

/// The JSON Schema dialect every audit schema declares.
pub const SCHEMA_DIALECT: &str = "https://json-schema.org/draft/2020-12/schema";

/// The registrations that describe a format, filtered by `keep`.
///
/// The probe types declared inside `#[cfg(test)] mod tests` are left out: they exist to
/// exercise the attribute and reach no record, so a schema that listed them would promise
/// shapes no consumer ever meets. They are recognised by `::tests::` in the type path, which
/// is where a type declared in such a module always sits.
fn registrations(keep: impl Fn(&Registration) -> bool) -> Vec<&'static Registration> {
    let mut regs: Vec<&Registration> = Registration::all()
        .filter(|r| !(r.type_name)().contains("::tests::"))
        .filter(|r| keep(r))
        .collect();
    regs.sort_by_key(|r| (r.type_name)());
    regs
}

/// Strip `null` from every optional property, in place and at every depth.
///
/// A field with no value is left out of the record; nothing emits `null`. The schema
/// generator does not know that — it renders `Option<T>` as "T or null" — so without this
/// the schema would promise a shape the emitter cannot produce, and a consumer would write a
/// parser for a value they will never see. A property that is required keeps whatever it
/// has: `null` there would be a real value, not an absence.
fn drop_null_from_optionals(schema: &mut Value) {
    if let Some(object) = schema.as_object_mut() {
        let required: Vec<&str> = object
            .get("required")
            .and_then(Value::as_array)
            .map(|r| r.iter().filter_map(Value::as_str).collect())
            .unwrap_or_default();
        let optional: Vec<String> = object
            .get("properties")
            .and_then(Value::as_object)
            .map(|p| {
                p.keys()
                    .filter(|name| !required.contains(&name.as_str()))
                    .cloned()
                    .collect()
            })
            .unwrap_or_default();
        if let Some(properties) = object.get_mut("properties").and_then(Value::as_object_mut) {
            for name in optional {
                if let Some(spec) = properties.get_mut(&name) {
                    drop_null_alternative(spec);
                }
            }
        }
        for value in object.values_mut() {
            drop_null_from_optionals(value);
        }
    } else if let Some(array) = schema.as_array_mut() {
        for value in array {
            drop_null_from_optionals(value);
        }
    }
}

/// Remove the `null` alternative from one property, in whichever of the two forms the
/// generator wrote it: a type list for a scalar, an `anyOf` branch for a type that has a
/// definition of its own.
fn drop_null_alternative(spec: &mut Value) {
    let Some(object) = spec.as_object_mut() else {
        return;
    };
    if let Some(kinds) = object.get("type").and_then(Value::as_array) {
        let kept: Vec<Value> = kinds.iter().filter(|k| *k != "null").cloned().collect();
        if kept.len() != kinds.len() {
            let kept = if let [only] = kept.as_slice() {
                only.clone()
            } else {
                Value::Array(kept)
            };
            object.insert("type".into(), kept);
        }
    }
    let Some(branches) = object.get("anyOf").and_then(Value::as_array) else {
        return;
    };
    let kept: Vec<Value> = branches
        .iter()
        .filter(|branch| branch["type"] != "null")
        .cloned()
        .collect();
    // Unchanged, or nothing but `null` — which would leave the property with no schema at
    // all, so it stays as the generator wrote it.
    if kept.len() == branches.len() || kept.is_empty() {
        return;
    }
    // One alternative left, and it is an object, so it is the property's schema and takes the
    // place of the branch list. Keys the property already carries win: `description` there is
    // the field's own doc comment, not the referenced type's. Anything else keeps its branch
    // list, because removing it would leave the property with no schema at all.
    match kept.as_slice() {
        [only] if only.is_object() => {
            object.remove("anyOf");
            for (key, value) in only.as_object().expect("checked by the guard") {
                object.entry(key.clone()).or_insert_with(|| value.clone());
            }
        }
        _ => {
            object.insert("anyOf".into(), Value::Array(kept));
        }
    }
}

/// The definitions the registrations contribute, plus every type they reference.
///
/// # Panics
///
/// If two registered types want the same `$defs` name. A definition is keyed by the type's
/// short name, so two types of one emitter called `Context` in different modules would
/// otherwise silently become one, and whichever lost would vanish from the schema while its
/// records kept being emitted.
fn definitions(regs: &[&Registration]) -> BTreeMap<String, Value> {
    let mut generator = SchemaGenerator::new(SchemaSettings::draft2020_12());
    let mut defs: BTreeMap<String, Value> = BTreeMap::new();
    let mut claimed: BTreeMap<String, &'static str> = BTreeMap::new();
    let mut claim = |name: &str, type_name: &'static str| {
        if let Some(other) = claimed.insert(name.to_owned(), type_name) {
            assert_eq!(
                other, type_name,
                "`{name}` is the schema name of two registered types, {other} and \
                 {type_name}. One would replace the other in the schema. Rename one of them."
            );
        }
    };
    for reg in regs {
        match reg.kind {
            Kind::Part | Kind::Context | Kind::Shape { .. } => {
                let (Some(schema), Some(name)) = (reg.schema, reg.schema_name) else {
                    continue;
                };
                let mut schema = schema(&mut generator).to_value();
                if let Some(object) = schema.as_object_mut() {
                    object.insert("x-audit-kind".into(), json!(reg.kind.as_str()));
                    object.insert("x-audit-type".into(), json!((reg.type_name)()));
                    if let Kind::Shape { record_type } = reg.kind {
                        object.insert("x-audit-record-type".into(), json!(record_type));
                        pin_record_type(object, record_type);
                    }
                }
                let name = name().to_string();
                claim(&name, (reg.type_name)());
                defs.insert(name, schema);
            }
            Kind::Values { .. } | Kind::Keys { .. } => {
                // A name is a string in a list, so JSON Schema gives it nowhere to carry its
                // own description. This map is where a variant's doc comment reaches a
                // consumer; without it the schema lists the names and explains none of them.
                let descriptions: BTreeMap<&str, &str> = reg
                    .kind
                    .names()
                    .iter()
                    .filter(|name| !name.doc.is_empty())
                    .map(|name| (name.text, name.doc))
                    .collect();
                let mut names: Vec<&str> = reg.kind.names().iter().map(|n| n.text).collect();
                names.sort_unstable();
                // A value vocabulary names the field its values fill; a key vocabulary names
                // the object its variants are keys of. Different extensions, because a
                // consumer and the format check both act on the difference: a new value
                // changes no format, a new key adds a field.
                let place = match reg.kind {
                    Kind::Keys { .. } => "x-audit-keys-of",
                    _ => "x-audit-field",
                };
                let mut def = json!({
                    "type": "string",
                    "enum": names,
                    "x-audit-kind": reg.kind.as_str(),
                    place: reg.kind.wire_place(),
                    "x-audit-type": (reg.type_name)(),
                });
                if !descriptions.is_empty()
                    && let Some(object) = def.as_object_mut()
                {
                    object.insert("x-audit-descriptions".into(), json!(descriptions));
                }
                // What sits under a key whose value is an object, rather than a string. The
                // pairing lives here and not on the object's own definition because the
                // object is shared: `context` takes keys from every emitter, and the crate
                // that declares the object cannot name a shape declared by a crate it has
                // never heard of. A consumer reads the key's shape from the schema of
                // whoever declared the key.
                let shapes: BTreeMap<&str, Value> = reg
                    .kind
                    .names()
                    .iter()
                    .filter_map(|name| {
                        name.shape
                            .map(|shape| (name.text, json!({ "$ref": format!("#/$defs/{shape}") })))
                    })
                    .collect();
                if !shapes.is_empty()
                    && let Some(object) = def.as_object_mut()
                {
                    object.insert("x-audit-key-shapes".into(), json!(shapes));
                }
                let name = short_type_name((reg.type_name)());
                claim(&name, (reg.type_name)());
                defs.insert(name, def);
            }
        }
    }
    // Types the parts reference but that are not registered themselves, if any, and every
    // registered type the generator chose to reference rather than inline. An unregistered
    // one still reaches a consumer, so it is kinded here too: the kind is how a reader of the
    // schema tells a value set from an object, and a definition without one says neither.
    for (name, schema) in generator.take_definitions(true) {
        let mut schema = schema;
        if let Some(object) = schema.as_object_mut() {
            let values = object.contains_key("enum")
                || object
                    .get("oneOf")
                    .and_then(Value::as_array)
                    .is_some_and(|variants| variants.iter().all(|v| v.get("const").is_some()));
            object
                .entry("x-audit-kind")
                .or_insert_with(|| json!(if values { "enum" } else { "part" }));
        }
        defs.entry(name).or_insert(schema);
    }
    for schema in defs.values_mut() {
        drop_null_from_optionals(schema);
    }
    link_value_sets(&mut defs, regs);
    defs
}

/// Pin a shape's `record_type` to the one value it carries.
///
/// The field is the one a consumer routes on, and for a given shape it is a constant, not a
/// choice from the vocabulary. `const` says exactly that, so a validator rejects a record
/// checked against the wrong shape instead of accepting any of the three.
fn pin_record_type(shape: &mut Map<String, Value>, record_type: &str) {
    let Some(property) = shape
        .get_mut("properties")
        .and_then(Value::as_object_mut)
        .and_then(|properties| properties.get_mut("record_type"))
        .and_then(Value::as_object_mut)
    else {
        return;
    };
    property.remove("type");
    property.insert("const".into(), json!(record_type));
}

/// Point every field that holds a closed set of values at the definition listing them.
///
/// A field's type is `WireStr` or a string stand-in, so the generator writes `"type":
/// "string"` and the value set sits in `$defs` with nothing referring to it. A consumer then
/// has a schema that accepts any string where the format allows two values. This links the
/// two, which is what makes the schema check a value rather than only describe it.
///
/// Skipped for a field marked `x-audit-open`, whose values come from whichever emitter
/// produced the record, and for a field fed by more than one vocabulary — `action_name` is
/// both. Those stay plain strings, because no single definition lists what they can hold.
fn link_value_sets(defs: &mut BTreeMap<String, Value>, regs: &[&Registration]) {
    let mut by_field: BTreeMap<&str, Vec<String>> = BTreeMap::new();
    for reg in regs {
        // Values only: a key vocabulary's names are keys of an object, not the values of a
        // property, so there is no property for them to point at.
        if let Kind::Values { field, .. } = reg.kind {
            by_field
                .entry(field)
                .or_default()
                .push(short_type_name((reg.type_name)()));
        }
    }
    let single: BTreeMap<&str, &String> = by_field
        .iter()
        .filter_map(|(field, owners)| match owners.as_slice() {
            [only] => Some((*field, only)),
            _ => None,
        })
        .collect();

    for schema in defs.values_mut() {
        let Some(properties) = schema.get_mut("properties").and_then(Value::as_object_mut) else {
            continue;
        };
        for (name, spec) in properties.iter_mut() {
            let Some(owner) = single.get(name.as_str()) else {
                continue;
            };
            let Some(object) = spec.as_object_mut() else {
                continue;
            };
            // Only a bare string. A property that already has a `$ref`, an `enum` or a
            // `const` says what it holds, and one marked open says it cannot be listed.
            let bare = object.get("type").and_then(Value::as_str) == Some("string")
                && !object.contains_key("enum")
                && !object.contains_key("const")
                && !object.contains_key("x-audit-open");
            if !bare {
                continue;
            }
            object.remove("type");
            object.insert("$ref".into(), json!(format!("#/$defs/{owner}")));
        }
    }
}

/// The crate schema of one crate: the definitions of the audit types it declares, for the
/// emitter it belongs to. Written by that crate's own unit tests, where its registrations are
/// certainly linked; committed as `audit-schema.json` at the crate root.
///
/// # Panics
///
/// If the crate registered nothing, or the registry is absent; see
/// [`Registration::require_registry`].
#[must_use]
pub fn crate_schema(defining_crate: &str) -> Value {
    Registration::require_registry();
    let regs = registrations(|r| r.defining_crate == defining_crate);
    let first = regs
        .first()
        .unwrap_or_else(|| panic!("crate `{defining_crate}` registered no audit types"));
    let emitter = first.emitter_name;
    let format = first.emitter_format;
    assert!(
        regs.iter().all(|r| r.emitter_name == emitter),
        "crate `{defining_crate}` registers types for more than one emitter"
    );
    let defs = definitions(&regs);
    json!({
        "$schema": SCHEMA_DIALECT,
        "title": format!("Audit types declared by crate {defining_crate}"),
        "x-audit-emitter": { "name": emitter, "format": format },
        "x-audit-crate": defining_crate,
        "$defs": Value::Object(defs.into_iter().collect::<Map<_, _>>()),
    })
}

/// Merge the committed crate schemas of one emitter into its schema.
///
/// # Panics
///
/// If the crate schemas name different emitters or formats, or two of them define the same
/// name differently.
#[must_use]
pub fn merge_crate_schemas(crate_schemas: &[Value]) -> Value {
    let first = crate_schemas.first().expect("at least one crate schema");
    let emitter = first["x-audit-emitter"].clone();
    let mut defs: BTreeMap<String, Value> = BTreeMap::new();
    for fragment in crate_schemas {
        assert_eq!(
            fragment["x-audit-emitter"], emitter,
            "crate schema {} names another emitter or format",
            fragment["x-audit-crate"]
        );
        for (name, def) in fragment["$defs"].as_object().expect("$defs") {
            if let Some(existing) = defs.get(name) {
                assert_eq!(
                    existing, def,
                    "`{name}` is defined differently by two crate schemas ({})",
                    fragment["x-audit-crate"]
                );
            }
            defs.insert(name.clone(), def.clone());
        }
    }
    let name = emitter["name"].as_str().unwrap_or("?");
    json!({
        "$schema": SCHEMA_DIALECT,
        "title": format!("Audit records emitted by {name}"),
        "x-audit-emitter": emitter,
        "$defs": Value::Object(defs.into_iter().collect::<Map<_, _>>()),
    })
}

/// The type's name without module path or generics: the key it gets under `$defs`.
#[must_use]
pub fn short_type_name(full: &str) -> String {
    let tail = full.rsplit("::").next().unwrap_or(full);
    tail.split('<').next().unwrap_or(tail).to_string()
}

/// The schema of everything the emitter `emitter` can put on the wire, from the registrations
/// linked into this binary. Complete only where every crate of the emitter is linked and
/// referenced; the committed schema is assembled from crate schemas instead, see the module
/// docs.
///
/// # Panics
///
/// If nothing is registered for the emitter, or the registry is absent.
#[must_use]
pub fn audit_schema_for(emitter: &str) -> Value {
    Registration::require_registry();
    let regs = registrations(|r| r.emitter_name == emitter);
    let first = regs
        .first()
        .unwrap_or_else(|| panic!("no audit types registered for emitter `{emitter}`"));
    let format = first.emitter_format;
    let defs = definitions(&regs);
    json!({
        "$schema": SCHEMA_DIALECT,
        "title": format!("Audit records emitted by {emitter}"),
        "x-audit-emitter": { "name": emitter, "format": format },
        "$defs": Value::Object(defs.into_iter().collect::<Map<_, _>>()),
    })
}

/// The schema as a pretty-printed document with a trailing newline, as committed.
///
/// # Panics
///
/// If the value does not serialize, which a schema built by this module always does.
#[must_use]
pub fn render(schema: &Value) -> String {
    let mut text = serde_json::to_string_pretty(schema).expect("a schema serializes");
    text.push('\n');
    text
}

/// The crate schema file of a crate: `audit-schema.json` at its root.
#[must_use]
pub fn crate_schema_path(manifest_dir: &str) -> std::path::PathBuf {
    std::path::Path::new(manifest_dir).join("audit-schema.json")
}

/// The environment variable that switches the crate schema and schema tests from comparing to
/// writing.
pub const UPDATE_ENV: &str = "LAKEKEEPER_UPDATE_AUDIT_SCHEMA";

/// Assert that the committed crate schema of `defining_crate` equals what its registry
/// generates, or write it when [`UPDATE_ENV`] is set. For use in that crate's own tests, so the
/// registrations are certainly linked.
///
/// # Panics
///
/// If the committed crate schema is missing or stale. That is the point: this is for use in
/// tests.
pub fn assert_crate_schema_committed(defining_crate: &str, manifest_dir: &str) {
    let path = crate_schema_path(manifest_dir);
    let generated = render(&crate_schema(defining_crate));
    if std::env::var_os(UPDATE_ENV).is_some() {
        std::fs::write(&path, &generated)
            .unwrap_or_else(|e| panic!("writing {}: {e}", path.display()));
        return;
    }
    let committed = std::fs::read_to_string(&path).unwrap_or_else(|e| {
        panic!(
            "cannot read the committed crate schema {}: {e}\n\nGenerate it with `just update-audit-schema`.",
            path.display()
        )
    });
    assert!(
        committed == generated,
        "the committed crate schema {} is not what the registry generates. Run `just update-audit-schema` and review the diff: it is what a consumer of the audit log will see.",
        path.display()
    );
}

/// Assert that no two vocabularies keying the same object declare the same key.
///
/// The `context` map of an authorization record is one flat object, and `keys_of =
/// "context"` is the one vocabulary form open to an emitter outside this repository. So two
/// products can reach the same key of the same object. One key, one meaning: a second
/// declaration is a second meaning at one path in one record, and whichever handler writes
/// last decides which of them a consumer sees.
///
/// Reads the whole registry rather than one crate's, so it sees every vocabulary linked into
/// the binary that runs it. Run from an emitting crate's own tests it therefore compares that
/// crate's keys against Lakekeeper's, which is the pairing that can clash.
///
/// A name reused at a *different* path is not this. `actor.principal` and `context.principal`
/// are two fields named for where they sit, which is why the reference tells a consumer to
/// address fields by path.
///
/// # Panics
///
/// If one object has the same key from two vocabularies.
pub fn assert_no_object_declares_a_key_twice() {
    Registration::require_registry();
    let mut owners: BTreeMap<(&str, &str), Vec<String>> = BTreeMap::new();
    for reg in registrations(|_| true) {
        let Kind::Keys { object, .. } = reg.kind else {
            continue;
        };
        let owner = short_type_name((reg.type_name)());
        for key in reg.kind.names().iter().map(|name| name.text) {
            owners.entry((object, key)).or_default().push(owner.clone());
        }
    }
    let clashes: Vec<String> = owners
        .iter()
        .filter(|(_, declared_by)| declared_by.len() > 1)
        .map(|((object, key), declared_by)| {
            format!(
                "{object}: `{key}` is declared by {}",
                declared_by.join(" and ")
            )
        })
        .collect();
    assert!(
        clashes.is_empty(),
        "these keys are declared twice for one object:\n  {}\n\n\
         A key names one thing. Two vocabularies declaring it for the same object put two \
         meanings at one path in one record, and the handler that writes last decides which \
         one a consumer sees. Rename one of them, or have the second use the first rather \
         than declaring its own.",
        clashes.join("\n  ")
    );
}

/// Every Rust source under `dir`, read into `out`.
fn rust_sources(dir: &std::path::Path, out: &mut Vec<String>) {
    let Ok(entries) = std::fs::read_dir(dir) else {
        return;
    };
    for entry in entries.flatten() {
        let path = entry.path();
        if path.is_dir() {
            if path.file_name().is_some_and(|name| name == "target") {
                continue;
            }
            rust_sources(&path, out);
        } else if path.extension().is_some_and(|e| e == "rs")
            && let Ok(text) = std::fs::read_to_string(&path)
        {
            out.push(text);
        }
    }
}

/// A name with its separators and case removed, so two spellings of one name compare equal.
///
/// The source names a variant, `DryRun`; the registry names what that variant puts on the
/// wire, `dry_run`. Both reduce to `dryrun`. A variant the attribute renames to something
/// else entirely still differs, which is the case worth a human reading it.
fn normalized(name: &str) -> String {
    name.chars()
        .filter(char::is_ascii_alphanumeric)
        .map(|c| c.to_ascii_lowercase())
        .collect()
}

/// The identifier following the first `prefix` in `block`, or `None` when there is none.
fn identifier_after(block: &str, prefix: &str) -> Option<String> {
    let at = block.find(prefix)? + prefix.len();
    let identifier: String = block[at..]
        .chars()
        .take_while(|c| c.is_ascii_alphanumeric() || *c == '_')
        .collect();
    (!identifier.is_empty()).then_some(identifier)
}

/// Every shape a key declares is a type that emitter registers.
///
/// `#[audit(holds = "...")]` names its shape as a string, so a typo compiles and publishes a
/// `$ref` into a customer-facing schema that resolves to nothing. Nothing else looks: the
/// generator copies the name through, and the format checker only diffs it against the last
/// one. This is what makes the name a reference rather than a spelling.
///
/// # Panics
///
/// If a key names a shape no registration of that emitter provides.
pub fn assert_declared_shapes_are_registered<E: super::AuditEmitter>() {
    Registration::require_registry();
    let known: BTreeSet<String> = registrations(|reg| reg.emitter_name == E::NAME)
        .iter()
        .filter(|reg| matches!(reg.kind, Kind::Part | Kind::Context | Kind::Shape { .. }))
        .filter_map(|reg| reg.schema_name.map(|name| name().to_string()))
        .collect();

    let mut dangling = Vec::new();
    for reg in registrations(|reg| reg.emitter_name == E::NAME) {
        let Kind::Keys { object, names } = reg.kind else {
            continue;
        };
        let owner = short_type_name((reg.type_name)());
        for name in names {
            if let Some(shape) = name.shape
                && !known.contains(shape)
            {
                dangling.push(format!(
                    "{owner}: key `{}` of `{object}` holds `{shape}`, which is not registered",
                    name.text
                ));
            }
        }
    }
    assert!(
        dangling.is_empty(),
        "these keys name a shape their emitter does not declare:\n  {}\n\n\
         `holds` is a reference to a registered type, written as its schema name. The schema \
         points a consumer at it by `$ref`, so a name nothing provides publishes a reference \
         that resolves to nothing. Check the spelling, and that the type carries \
         `#[audit_part]` and belongs to this emitter.",
        dangling.join("\n  ")
    );
}

/// Every `context` key an emitter declares is pushed by some call under `crates_dir`.
///
/// A key vocabulary is pinned by the schema: rename or drop a name and the format moves, and
/// the checker reports it. A `push_extra_context` call deleted in a refactor is invisible
/// there. The key leaves the wire, the enum that declares it stays, the schema diff is empty,
/// and a field a consumer reads is gone with nothing to announce it. This reads the registry
/// for the keys and the source for the pushes.
///
/// The source is read rather than a record captured because these keys ride on a record their
/// own crate does not assemble: an emitter outside Lakekeeper pushes keys onto an
/// authorization record that Lakekeeper stamps, so that crate has no record of its own to
/// capture them from.
///
/// One push site is enough to pass. A key pushed from two places passes while either remains.
///
/// # Panics
///
/// If a declared key has no push site, or if the scan finds no sources or no push sites,
/// which means it is pointed at the wrong tree.
pub fn assert_every_context_key_is_pushed<E: super::AuditEmitter>(crates_dir: &std::path::Path) {
    Registration::require_registry();

    let mut declared: BTreeMap<String, Vec<&'static str>> = BTreeMap::new();
    for reg in registrations(|reg| reg.emitter_name == E::NAME) {
        let Kind::Keys { object, names } = reg.kind else {
            continue;
        };
        if object != "context" {
            continue;
        }
        declared
            .entry(short_type_name((reg.type_name)()))
            .or_default()
            .extend(names.iter().map(|name| name.text));
    }
    assert!(
        !declared.is_empty(),
        "emitter `{}` has no `context` key vocabulary in this registry, so either it declares          none or the crate that declares one is not linked into this test binary.",
        E::NAME
    );

    let mut sources = Vec::new();
    rust_sources(crates_dir, &mut sources);
    assert!(
        sources.len() > 10,
        "only {} Rust sources under {}, so this is scanning the wrong tree",
        sources.len(),
        crates_dir.display()
    );

    let mut pushed: BTreeSet<(String, String)> = BTreeSet::new();
    for text in &sources {
        for (at, _) in text.match_indices("push_extra_context") {
            // The call, bounded generously: the key is its first argument, and the longest of
            // these calls wraps over a few lines. Bounded in CHARACTERS: a byte slice that
            // lands inside a multi-byte character panics, and these sources are full of em
            // dashes.
            let block: String = text[at..].chars().take(400).collect();
            for vocabulary in declared.keys() {
                if let Some(variant) = identifier_after(&block, &format!("{vocabulary}::")) {
                    pushed.insert((vocabulary.clone(), normalized(&variant)));
                }
            }
        }
    }
    assert!(
        !pushed.is_empty(),
        "no `push_extra_context` call under {} names a declared key, so this is scanning the \
         wrong tree",
        crates_dir.display()
    );

    let mut missing: Vec<String> = Vec::new();
    for (vocabulary, keys) in &declared {
        for key in keys {
            if !pushed.contains(&(vocabulary.clone(), normalized(key))) {
                missing.push(format!("{vocabulary}::{key}"));
            }
        }
    }
    assert!(
        missing.is_empty(),
        "these `context` keys are declared and pushed nowhere:\n  {}\n\n\
         A key nothing pushes is a field the schema promises and no record carries. Push it, \
         or drop it from the vocabulary and write the fragment its removal owes.",
        missing.join("\n  ")
    );
}

/// Whether `name` is one or more runs of `[a-z0-9]` joined by single underscores, starting
/// with a letter.
///
/// Checking the characters alone would accept a leading, trailing or doubled underscore.
fn is_lower_snake_case(name: &str) -> bool {
    name.starts_with(|c: char| c.is_ascii_lowercase())
        && name.split('_').all(|segment| {
            !segment.is_empty()
                && segment
                    .chars()
                    .all(|c| c.is_ascii_lowercase() || c.is_ascii_digit())
        })
}

/// Assert that the wire names `defining_crate` declares are house style: usable by a consumer
/// at all, and `lower_snake_case` unless the declaring type is marked `external_values`.
///
/// Every key is held to the rule, and so is every value, because a record spells its names
/// the way the rest of the log does. A value vocabulary spelled somewhere else is marked and
/// skipped. The default is to check, so a vocabulary cannot go unchecked by being left off a
/// list.
///
/// Renaming a name shows up as a schema difference and the format check calls it a breaking
/// change. Adding one does not, because an addition breaks no consumer, so a new name spelled
/// the wrong way would reach a release unremarked. This is the check for that.
///
/// # Panics
///
/// If a name is empty, carries whitespace, or is not `lower_snake_case` without being marked.
pub fn assert_wire_values_are_house_style(defining_crate: &str) {
    Registration::require_registry();
    let mut malformed = Vec::new();
    for reg in registrations(|r| r.defining_crate == defining_crate) {
        let Some(field) = reg.kind.wire_place() else {
            continue;
        };
        if reg.external_values {
            continue;
        }
        let owner = short_type_name((reg.type_name)());
        let what = if matches!(reg.kind, Kind::Keys { .. }) {
            "key"
        } else {
            "value"
        };
        for value in reg.kind.names().iter().map(|name| name.text) {
            if value.is_empty() || value.chars().any(char::is_whitespace) {
                malformed.push(format!("{field}: {owner} -> {value:?} is unusable"));
            } else if !is_lower_snake_case(value) {
                malformed.push(format!(
                    "{field}: {owner} -> {what} `{value}` is not lower_snake_case"
                ));
            }
        }
    }
    assert!(
        malformed.is_empty(),
        "these wire names are not house style:\n  {}\n\n\
         A name is one or more runs of `[a-z0-9]` joined by single underscores, starting with \
         a letter, which is how every line in this log spells a name. An enum that lost its \
         case style, gained a different one, or carries a hand-written rename that does not \
         follow it lands here. Fix the spelling now: once released, changing it renames \
         something consumers match on. If these values are spelled somewhere else — another \
         product publishes them, or they mirror a vocabulary that does — add `external_values` \
         to the enum's `#[audit_part(...)]` and name that vocabulary in its doc comment.",
        malformed.join("\n  ")
    );
}
